const updateSessionPayloads = `-- name: UpdateSessionPayloads :many
WITH payload_updates AS (
    SELECT
        UNNEST($1::TEXT[]) AS session_id,
        UNNEST($2::INT[]) AS expected_version,
        UNNEST($3::BYTEA[]) AS data
)
UPDATE backend.sessions AS sessions
SET data = payload_updates.data,
    version = sessions.version + 1
FROM payload_updates
WHERE sessions.session_id = payload_updates.session_id
  AND sessions.version = payload_updates.expected_version
  AND sessions.state IN ('pending', 'authenticated')
  AND sessions.expires_at > NOW()
RETURNING sessions.session_id, sessions.version
`

type UpdateSessionPayloadsParams struct {
	SessionIds       []string `db:"session_ids" json:"session_ids"`
	ExpectedVersions []int32  `db:"expected_versions" json:"expected_versions"`
	Payloads         [][]byte `db:"payloads" json:"payloads"`
}

type UpdateSessionPayloadsRow struct {
	SessionID string `db:"session_id" json:"session_id"`
	Version   int32  `db:"version" json:"version"`
}

func (q *Queries) UpdateSessionPayloads(ctx context.Context, arg *UpdateSessionPayloadsParams) ([]*UpdateSessionPayloadsRow, error) {
	rows, err := q.db.Query(ctx, updateSessionPayloads, arg.SessionIds, arg.ExpectedVersions, arg.Payloads)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []*UpdateSessionPayloadsRow
	for rows.Next() {
		var i UpdateSessionPayloadsRow
		if err := rows.Scan(&i.SessionID, &i.Version); err != nil {
			return nil, err
		}
		items = append(items, &i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
